CREATE OR REPLACE FUNCTION public.record_receipt(_data jsonb,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid:=gen_random_uuid(); existing uuid; party uuid:=nullif(_data->>'party_id','')::uuid; con uuid:=nullif(_data->>'contract_id','')::uuid; amt numeric:=round((_data->>'amount_excl_vat')::numeric,2); vat numeric:=round((_data->>'vat_amount')::numeric,2); token uuid:=(_data->>'idempotency_key')::uuid; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); IF token IS NULL THEN RAISE EXCEPTION 'معرف منع التكرار مطلوب'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(token::text,0)); SELECT id INTO existing FROM public.receipts WHERE idempotency_key=token; IF existing IS NOT NULL THEN RETURN existing; END IF; IF party IS NULL OR NOT EXISTS(SELECT 1 FROM public.parties WHERE id=party AND archived_at IS NULL AND merged_into_id IS NULL) OR amt IS NULL OR amt<=0 OR vat IS NULL OR vat<0 OR nullif(_data->>'paid_at','') IS NULL OR nullif(btrim(_data->>'method'),'') IS NULL THEN RAISE EXCEPTION 'العميل وتاريخ السداد والطريقة والمبالغ مطلوبة'; END IF; IF con IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contracts WHERE id=con AND party_id=party AND status IN ('draft','active')) THEN RAISE EXCEPTION 'العقد لا يخص العميل أو مغلق'; END IF; INSERT INTO public.receipts(id,party_id,contract_id,booking_id,paid_at,method,amount_excl_vat,vat_amount,amount_incl_vat,proof_file,recorded_by,reason,idempotency_key) VALUES(k,party,con,nullif(_data->>'booking_id','')::uuid,(_data->>'paid_at')::timestamptz,_data->>'method',amt,vat,amt+vat,nullif(_data->>'proof_file',''),auth.uid(),_reason,token); PERFORM public.finance_audit('RECEIPT_RECORDED','receipts',k,NULL,(SELECT to_jsonb(r) FROM public.receipts r WHERE id=k),_reason); RETURN k; END $$;
REVOKE ALL ON FUNCTION public.record_receipt(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_receipt(jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.allocate_receipt(_receipt uuid,_installment uuid,_amount_excl_vat numeric,_vat_amount numeric,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.receipts; i public.installments; c public.contracts; k uuid:=gen_random_uuid(); used_ex numeric; used_vat numeric; owed_ex numeric; owed_vat numeric; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); SELECT * INTO r FROM public.receipts WHERE id=_receipt FOR UPDATE; IF NOT FOUND OR r.status='reversed' OR r.reverses_id IS NOT NULL OR r.archived_at IS NOT NULL THEN RAISE EXCEPTION 'إيصال غير صالح للتخصيص'; END IF; SELECT * INTO i FROM public.installments WHERE id=_installment FOR UPDATE; IF NOT FOUND OR i.status='waived' THEN RAISE EXCEPTION 'قسط غير صالح للتخصيص'; END IF; SELECT * INTO c FROM public.contracts WHERE id=i.contract_id; IF c.party_id IS DISTINCT FROM r.party_id OR c.status<>'active' OR (r.contract_id IS NOT NULL AND r.contract_id<>c.id) OR NOT r.vat_documented THEN RAISE EXCEPTION 'العميل أو العقد أو بيانات الضريبة لا تطابق التخصيص'; END IF; IF _amount_excl_vat IS NULL OR _vat_amount IS NULL OR _amount_excl_vat<0 OR _vat_amount<0 OR _amount_excl_vat+_vat_amount<=0 OR _amount_excl_vat<>round(_amount_excl_vat,2) OR _vat_amount<>round(_vat_amount,2) THEN RAISE EXCEPTION 'مبلغ التخصيص غير صالح'; END IF; SELECT coalesce(sum(amount_excl_vat),0),coalesce(sum(vat_amount),0) INTO used_ex,used_vat FROM public.receipt_allocations WHERE receipt_id=r.id; SELECT coalesce(sum(a.amount_excl_vat),0),coalesce(sum(a.vat_amount),0) INTO owed_ex,owed_vat FROM public.receipt_allocations a JOIN public.receipts x ON x.id=a.receipt_id WHERE a.installment_id=i.id AND x.status IN ('recorded','verified') AND x.reverses_id IS NULL AND x.archived_at IS NULL; IF used_ex+_amount_excl_vat>r.amount_excl_vat OR used_vat+_vat_amount>r.vat_amount OR owed_ex+_amount_excl_vat>i.amount_excl_vat OR owed_vat+_vat_amount>i.vat_amount THEN RAISE EXCEPTION 'التخصيص يتجاوز مبلغ الإيصال أو القسط'; END IF; INSERT INTO public.receipt_allocations(id,receipt_id,installment_id,amount_excl_vat,vat_amount,amount_incl_vat) VALUES(k,r.id,i.id,_amount_excl_vat,_vat_amount,_amount_excl_vat+_vat_amount); IF r.contract_id IS NULL THEN UPDATE public.receipts SET contract_id=c.id WHERE id=r.id; PERFORM public.finance_audit('RECEIPT_LINKED','receipts',r.id,to_jsonb(r),(SELECT to_jsonb(x) FROM public.receipts x WHERE id=r.id),_reason); END IF; PERFORM public.finance_audit('RECEIPT_ALLOCATED','receipt_allocations',k,NULL,(SELECT to_jsonb(x) FROM public.receipt_allocations x WHERE id=k),_reason); PERFORM public.refresh_installments(c.id); RETURN k; END $$;
REVOKE ALL ON FUNCTION public.allocate_receipt(uuid,uuid,numeric,numeric,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.allocate_receipt(uuid,uuid,numeric,numeric,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.verify_receipt(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.receipts; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); SELECT * INTO r FROM public.receipts WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.status<>'recorded' OR r.reverses_id IS NOT NULL OR r.archived_at IS NOT NULL OR r.party_id IS NULL OR r.paid_at IS NULL OR NOT r.vat_documented THEN RAISE EXCEPTION 'الإيصال غير مكتمل أو غير قابل للتحقق'; END IF; UPDATE public.receipts SET status='verified',verified_by=auth.uid(),verified_at=now() WHERE id=r.id; PERFORM public.finance_audit('RECEIPT_VERIFIED','receipts',r.id,to_jsonb(r),(SELECT to_jsonb(x) FROM public.receipts x WHERE id=r.id),_reason); IF r.contract_id IS NOT NULL THEN PERFORM public.refresh_installments(r.contract_id); END IF; END $$;
REVOKE ALL ON FUNCTION public.verify_receipt(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.verify_receipt(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.reverse_receipt(_id uuid,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.receipts; k uuid:=gen_random_uuid(); a record; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); SELECT * INTO r FROM public.receipts WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.status='reversed' OR r.reverses_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.receipts WHERE reverses_id=r.id) THEN RAISE EXCEPTION 'الإيصال معكوس أو غير صالح'; END IF; INSERT INTO public.receipts(id,party_id,contract_id,booking_id,paid_at,method,amount_excl_vat,vat_amount,amount_incl_vat,vat_documented,recorded_by,status,reverses_id,reason) VALUES(k,r.party_id,r.contract_id,r.booking_id,now(),r.method,-r.amount_excl_vat,-r.vat_amount,-r.amount_incl_vat,r.vat_documented,auth.uid(),'reversed',r.id,_reason); UPDATE public.receipts SET status='reversed' WHERE id=r.id; FOR a IN SELECT * FROM public.receipt_allocations WHERE receipt_id=r.id LOOP INSERT INTO public.receipt_allocations(receipt_id,installment_id,amount_excl_vat,vat_amount,amount_incl_vat,reverses_id) VALUES(k,a.installment_id,-a.amount_excl_vat,-a.vat_amount,-a.amount_incl_vat,a.id); END LOOP; PERFORM public.finance_audit('RECEIPT_REVERSED','receipts',r.id,to_jsonb(r),(SELECT to_jsonb(x) FROM public.receipts x WHERE id=r.id),_reason); PERFORM public.finance_audit('RECEIPT_REVERSAL_CREATED','receipts',k,NULL,(SELECT to_jsonb(x) FROM public.receipts x WHERE id=k),_reason); IF r.contract_id IS NOT NULL THEN PERFORM public.refresh_installments(r.contract_id); END IF; RETURN k; END $$;
REVOKE ALL ON FUNCTION public.reverse_receipt(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reverse_receipt(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.waive_installment(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.installments; BEGIN PERFORM public.finance_assert_writer(); PERFORM public._assert_reason(_reason); SELECT * INTO i FROM public.installments WHERE id=_id FOR UPDATE; IF NOT FOUND OR i.status IN ('paid','waived') OR EXISTS(SELECT 1 FROM public.receipt_allocations WHERE installment_id=i.id) THEN RAISE EXCEPTION 'لا يمكن إعفاء قسط مسدد أو مخصص؛ راجع الإيصالات أولًا'; END IF; UPDATE public.installments SET status='waived',waiver_reason=_reason,waived_by=auth.uid(),waived_at=now() WHERE id=i.id; PERFORM public.finance_audit('INSTALLMENT_WAIVED','installments',i.id,to_jsonb(i),(SELECT to_jsonb(x) FROM public.installments x WHERE id=i.id),_reason); END $$;
REVOKE ALL ON FUNCTION public.waive_installment(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.waive_installment(uuid,text) TO authenticated;
INSERT INTO public.receipts(id,party_id,method,amount_excl_vat,vat_amount,amount_incl_vat,vat_documented,proof_file,recorded_by,reason,archived_at,recorded_at) SELECT c.id,t.party_id,'legacy_unknown',round(c.amount,2),NULL,NULL,false,c.proof_path,c.created_by,'نقل تحصيل تاريخي؛ تاريخ السداد والضريبة غير موثقين',CASE WHEN c.is_archived THEN coalesce(c.archived_at,c.updated_at) END,c.created_at FROM public.unit_collections c LEFT JOIN public.tenant_accounts t ON t.id=c.tenant_account_id ON CONFLICT(id) DO NOTHING;
INSERT INTO public.receipt_legacy_sources(source_table,source_id,receipt_id,unit_id,original_amount,rounded_amount,source_recorded_at,source_archived) SELECT 'unit_collections',c.id,c.id,c.unit_id,c.amount,round(c.amount,2),c.created_at,c.is_archived FROM public.unit_collections c ON CONFLICT(source_table,source_id) DO NOTHING;
INSERT INTO public.receipts(id,party_id,booking_id,method,amount_excl_vat,vat_amount,amount_incl_vat,vat_documented,recorded_by,reason,archived_at,recorded_at) SELECT i.id,coalesce(t.party_id,b.party_id),i.booking_id,coalesce(i.payment_method,'legacy_unknown'),round(i.paid_amount,2),NULL,NULL,false,i.created_by,'نقل دفعة فاتورة تاريخية؛ احتمال التكرار يحتاج مراجعة',i.archived_at,coalesce(i.paid_at,i.created_at) FROM public.invoices i LEFT JOIN public.tenant_accounts t ON t.id=i.tenant_account_id LEFT JOIN public.bookings b ON b.id=i.booking_id WHERE i.paid_amount<>0 ON CONFLICT(id) DO NOTHING;
INSERT INTO public.receipt_legacy_sources(source_table,source_id,receipt_id,unit_id,original_amount,rounded_amount,source_recorded_at,source_archived) SELECT 'invoices',i.id,i.id,i.unit_id,i.paid_amount,round(i.paid_amount,2),coalesce(i.paid_at,i.created_at),i.archived_at IS NOT NULL FROM public.invoices i WHERE i.paid_amount<>0 ON CONFLICT(source_table,source_id) DO NOTHING;
INSERT INTO public.audit_log(actor_role,action,entity_table,entity_id,after_data,context) SELECT 'system','LEGACY_RECEIPT_BACKFILL','receipts',r.id::text,to_jsonb(r),jsonb_build_object('reason','نقل بقيمة مقربة مع حفظ الأصل وعدم استنتاج الضريبة أو التحقق') FROM public.receipts r JOIN public.receipt_legacy_sources s ON s.receipt_id=r.id WHERE NOT EXISTS(SELECT 1 FROM public.audit_log a WHERE a.action='LEGACY_RECEIPT_BACKFILL' AND a.entity_id=r.id::text);
CREATE OR REPLACE VIEW public.receipt_reconciliation WITH(security_invoker=true) AS SELECT s.source_table,date_trunc('month',s.source_recorded_at)::date AS month,s.unit_id,s.source_archived,count(*) AS rows,sum(s.original_amount) AS original_total,sum(s.rounded_amount) AS rounded_total,sum(r.amount_excl_vat) AS receipt_total,sum(s.rounded_amount-s.original_amount) AS precision_difference,sum(r.amount_excl_vat-s.rounded_amount) AS unexplained_difference,count(*) FILTER(WHERE s.resolution='review') AS pending_review FROM public.receipt_legacy_sources s JOIN public.receipts r ON r.id=s.receipt_id GROUP BY s.source_table,date_trunc('month',s.source_recorded_at)::date,s.unit_id,s.source_archived;
GRANT SELECT ON public.receipt_reconciliation TO authenticated,service_role;
SELECT source_table,sum(original_total) AS old_total,sum(receipt_total) AS new_total,sum(precision_difference) AS precision_difference,sum(unexplained_difference) AS unexplained_difference FROM public.receipt_reconciliation GROUP BY source_table;